    # Repeated colored bars are endpoint cues. A lone 3 lies on a ray from
    # a bar, marking where that ray changes to 4. Draw rays of 3 back toward
    # the corresponding boundary bar, retaining all original markers.
    bars=[]
    for r in range(h):
        cells=[c for c,v in enumerate(grid[r]) if v!=bg]
        if len(cells)>=2: bars.append(('row',r,min(cells),max(cells),grid[r][cells[0]]))
    for c in range(w):
        cells=[r for r in range(h) if grid[r][c]!=bg]
        if len(cells)>=2: bars.append(('col',c,min(cells),max(cells),grid[cells[0]][c]))
    # Rays are associated to the nearest boundary bar of their color.
    for r in range(h):
      for c in range(w):
        if grid[r][c]==bg: continue
        if c in (0,w-1):
            # vertical ray toward its column-edge endpoint
            step=1 if c==0 else -1
            rr=r+step
            while 0<=rr<h and grid[rr][c]==bg:
                out[rr][c]=3; rr+=step
        elif r in (0,h-1):
            step=1 if r==0 else -1
            cc=c+step
            while 0<=cc<w and grid[r][cc]==bg:
                out[r][cc]=3; cc+=step
    # For task input, diagonal 3 markers project as vertical/horizontal rays toward 7 bars.
    for r,c in [(rr,cc) for rr in range(h) for cc in range(w) if grid[rr][cc]==3]:
        if r==0 or r==h-1 or c==0 or c==w-1: continue
        # nearest horizontal bar row, project along its column to boundary
        if c>=w//2:
            for rr in range(r):
                if out[rr][c]==bg: out[rr][c]=3
        else:
            for rr in range(r+1,h):
                if out[rr][c]==bg: out[rr][c]=3
    return out
